import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/kickimgr.html","title":"kickimgr","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.56,"words":169},"filePathRelative":"kickimgr.md"}`),a={name:`kickimgr.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="kickimgr" tabindex="-1"><a class="header-anchor" href="#kickimgr"><span>kickimgr</span></a></h1><p><a href="./Neutralinojs.html">Neutralinojs</a>で作った<a href="./MdImgr.html">MdImgr</a>のランチャー。<a href="./自作アプリ.html">自作アプリ</a></p><ul><li><a href="https://github.com/karino2/kickimgr" target="_blank" rel="noopener noreferrer">karino2/kickimgr: Neutralinojsを使ったMdImgrのランチャー</a></li></ul><h2 id="概要" tabindex="-1"><a class="header-anchor" href="#概要"><span>概要</span></a></h2><p><a href="./MdImgr.html">MdImgr</a>は実質ブログとRandomThoughtsでしか使っていないので、これら用に簡単に起動出来るランチャーを作りたい。</p><p>ディレクトリ名だけ指定したら所定の場所にディレクトリを掘ってMdImgrを起動する。 ブログかRandomThoughtsかで合わせたテンプレートを引数にわたす。</p><p>neuでは全部小文字のアプリが多いので、kickimgrと全部小文字にしておく。（結局バンドルが必須だったのでKickImgrにしておくんだったと後悔）</p><p>とりあえずパスは決め打ちでハードコードでいいだろう。user_path.jsをcloneした人が書き換える感じにしておく（まぁ自分しか使わないが別環境に持っていく時用に）。</p><p><a href="./Neutralinojs.html">Neutralinojs</a>を使った簡単なGUIランチャーの例として作ってみた。今後似たような事をしたければこれを変更していこう。</p><h2 id="mac用のビルド" tabindex="-1"><a class="header-anchor" href="#mac用のビルド"><span>Mac用のビルド</span></a></h2><p>neu buildでバイナリが作られるが、これはresources.neuが別に作られてしまう。</p><p><code>neu build --embed-resources</code> でシングルバイナリが出来るらしいが、これは起動すらせずにzshにkillされてしまう。なんかMacはsingle binaryに出来ないっぽいか？</p><p>とりあえず以下にはバンドルを作る手順も書いてある。</p><p><a href="https://neutralino.js.org/docs/distribution/overview" target="_blank" rel="noopener noreferrer">Distribution Overview - Neutralinojs</a></p><p>面倒だがやってみるか。</p><p>以下をプロジェクトフォルダの中にcloneして作業するらしい。</p><p><a href="https://github.com/hschneider/neutralino-build-scripts" target="_blank" rel="noopener noreferrer">hschneider/neutralino-build-scripts</a></p><p>なんかbuild-scripts下を全部コピーしろ、とか書いてあるが、さすがにそれは嫌では？ ということでプロジェクトのフォルダにbuild-scriptsをcloneしたあとに<code>_app_scaffolds</code>だけコピーして<code>$ build-scripts/build-mac.sh</code> したら出来たっぽい？</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ cp -r dist/mac_arm64/kickimgr.app /Applications/kickimgr.app</span>
<span class="line">$ open -a kickimgr</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>一応動いた。これでいいか。</p><p>バンドルにするならKickImgrとCamelCaseにするんだったなぁ。</p>`,21)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};